class TombstoneIndex:
    def __init__(self):
        self.vectors = {}
        self.deleted = set()

    def upsert(self, vector_id, vec):
        self.vectors[vector_id] = vec

    def delete(self, vector_id):
        self.deleted.add(vector_id)

    def search(self, query, k, distance_fn):
        scanned = 0
        results = []
        for vector_id, vec in self.vectors.items():
            scanned += 1
            if vector_id in self.deleted:
                continue
            results.append((vector_id, distance_fn(query, vec)))
        results.sort(key=lambda pair: pair[1])
        return results[:k], scanned

    def compact(self):
        self.vectors = {v: vec for v, vec in self.vectors.items() if v not in self.deleted}
        self.deleted = set()


def dist(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b)) ** 0.5


index = TombstoneIndex()
for i in range(20):
    index.upsert(f"doc{i}", [float(i), 0.0])

# Simulate months of churn with no compaction: 16 of the original 20
# documents get deleted (expired offers, retired policies), while only
# 5 brand-new documents are added -- a realistic shrinking collection.
for i in range(16):
    index.delete(f"doc{i}")
for i in range(20, 25):
    index.upsert(f"doc{i}", [float(i), 0.0])

_, scanned_before = index.search([0.0, 0.0], k=3, distance_fn=dist)
print(scanned_before, len(index.vectors), len(index.deleted))

index.compact()
_, scanned_after = index.search([0.0, 0.0], k=3, distance_fn=dist)
print(scanned_after, len(index.vectors), len(index.deleted))

def broken_reindex(documents, store, embed_fn):
    for doc in documents:
        new_id = len(store)
        store[new_id] = (embed_fn(doc["text"]), doc["text"])


def correct_reindex(documents, store, embed_fn):
    for doc in documents:
        store[doc["id"]] = (embed_fn(doc["text"]), doc["text"])


def toy_embed(text):
    return [sum(ord(c) for c in text) % 97]


documents = [{"id": "policy-1", "text": "Employees get 15 vacation days."}]

broken_store = {}
broken_reindex(documents, broken_store, toy_embed)
broken_reindex(documents, broken_store, toy_embed)   # nightly reprocessing run #2
print(len(broken_store))

correct_store = {}
correct_reindex(documents, correct_store, toy_embed)
correct_reindex(documents, correct_store, toy_embed)  # nightly reprocessing run #2
print(len(correct_store))

store = {
    "policy-1": {
        "vector": [0.20, 0.81, 0.10],   # embedding of the ORIGINAL text below
        "text": "Employees accrue 1 vacation day per month.",
        "last_reviewed": "2024-01-10",
    }
}


def patch_metadata_only(store, doc_id, **fields):
    store[doc_id].update(fields)


def update_content(store, doc_id, new_text, embed_fn):
    store[doc_id]["text"] = new_text
    store[doc_id]["vector"] = embed_fn(new_text)   # re-embed -- content actually changed


def toy_embed(text):
    s = sum(ord(c) for c in text)
    return [(s % 5) / 5, (s % 7) / 7, (s % 11) / 11]


# The policy text changes (1 day/month -> 2 days/month) but only the
# review timestamp gets patched -- a common, easy-to-make mistake.
patch_metadata_only(store, "policy-1", last_reviewed="2024-06-01")
store["policy-1"]["text"] = "Employees accrue 2 vacation days per month."  # changed by hand, vector untouched

print(store["policy-1"]["vector"])       # still describes the OLD "1 day" text
print(store["policy-1"]["text"])          # now says "2 days"

update_content(store, "policy-1", "Employees accrue 2 vacation days per month.", toy_embed)
print(store["policy-1"]["vector"])       # now actually re-embedded from the NEW text

