import math

def required_overfetch(k, selectivity):
    return math.ceil(k / selectivity)

print(required_overfetch(10, 0.5))
print(required_overfetch(10, 0.05))
print(required_overfetch(10, 0.001))

def dist(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b)) ** 0.5


def adaptive_post_filter_search(query, documents, tenant, k, dist_fn, growth=3, max_candidates=None):
    if max_candidates is None:
        max_candidates = len(documents)
    n = k
    trace = []
    while True:
        candidates = sorted(documents, key=lambda name: dist_fn(query, documents[name][0]))[:n]
        matched = [name for name in candidates if documents[name][1] == tenant]
        trace.append((n, len(matched)))
        if len(matched) >= k or n >= max_candidates:
            return matched[:k], n, trace
        n = min(n * growth, max_candidates)


